export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  // Дубли строк — данность ADR-0011: tables-upsert-records не уникальный
  // индекс, дубли схлопываются при чтении. Здесь только счёт, без записи и
  // удаления (Q42, вариант 2). «Лишние строки» = сумма (n-1) по ключам,
  // встретившимся больше одного раза; строку с пустой половиной ключа не судим.
  const countDupes = (records, keyFields) => {
    const seen = {};
    let rows = 0;
    let dupes = 0;
    arr(records).map(flat).forEach((r) => {
      const parts = keyFields.map((f) => str(r[f]));
      if (parts.some((p) => p === '')) return;
      rows += 1;
      const k = parts.join('|');
      if (seen[k]) { dupes += 1; } else { seen[k] = true; }
    });
    return { rows: rows, dupes: dupes };
  };
  const regs = countDupes(inputs.registrations, ['event_id', 'telegram_id']);
  const stf = countDupes(inputs.eventStaff, ['event_id', 'telegram_id']);
  const tgts = countDupes(inputs.broadcastTargets, ['broadcast_id', 'telegram_id']);

  const obj = (v) => v && typeof v === 'object' && !Array.isArray(v) ? v : {};
  const texts = obj(inputs.texts);
  const date = new Intl.DateTimeFormat('ru-RU', { timeZone: 'Asia/Tashkent', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
  const subst = (tpl, vars) => String(tpl).replace(/\{([A-Za-z0-9_]+)\}/g, (m, name) => (vars[name] === undefined || vars[name] === null ? m : String(vars[name])));
  const line = (key, vars) => subst(texts[key] === undefined ? key : texts[key], vars);

  const total = regs.dupes + stf.dupes + tgts.dupes;
  const report = [
    line('dedup.title', { date: date }),
    '',
    line('dedup.registrations', { rows: regs.rows, dupes: regs.dupes }),
    line('dedup.event_staff', { rows: stf.rows, dupes: stf.dupes }),
    line('dedup.broadcast_targets', { rows: tgts.rows, dupes: tgts.dupes }),
    '',
    line('dedup.total', { total: total })
  ].join('\n');

  // Получатель — строки staff: единственный в проекте список организаторов
  // (Q18: отдельного канала админов нет). Сегодня это ровно владелец проекта.
  const seenR = {};
  const recipients = arr(inputs.staff).map(flat)
    .map((r) => str(r.telegram_id))
    .filter((id) => id !== '')
    .filter((id) => { if (seenR[id]) return false; seenR[id] = true; return true; })
    .map((id) => ({ telegramId: id }));

  return {
    date: date,
    rows: { registrations: regs.rows, event_staff: stf.rows, broadcast_targets: tgts.rows },
    dupes: { registrations: regs.dupes, event_staff: stf.dupes, broadcast_targets: tgts.dupes },
    total: total,
    recipients: recipients,
    text: report
  };
};
